import {normalize} from './search.js';
const $=id=>document.getElementById(id);let records=[],selected=null,dirty=false;
const message=text=>$('status').textContent=text;
const el=(tag,text)=>{const node=document.createElement(tag);if(text)node.textContent=text;return node};
async function api(url,options={}){const r=await fetch(url,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await r.json();if(!r.ok){if(r.status===401)showLogin();throw Error(data.error||'No se pudo completar la operación')}return data}
function markDirty(value=true){dirty=value;$('dirty').textContent=value?'Cambios sin guardar':''}
function showLogin(){$('login').hidden=false;$('workspace').hidden=true;$('logout').hidden=true}
function list(){const q=normalize($('filter').value);$('list').replaceChildren();for(const m of records.filter(m=>normalize(m.name+' '+m.city).includes(q))){const b=el('button',m.name+(m.publicationStatus==='draft'?' · borrador':''));b.type='button';b.setAttribute('aria-pressed',String(selected?.id===m.id));b.onclick=()=>{if(dirty&&!confirm('Hay cambios sin guardar. ¿Querés descartarlos?'))return;select(m)};$('list').append(b)}}
function personRow(person={id:crypto.randomUUID(),name:'',aliases:[],role:'Conductor/a',program:''}){const row=el('div');row.className='person-row';row.dataset.id=person.id;
 for(const [key,label] of [['name','Nombre'],['aliases','Alias (separados por coma)'],['role','Rol'],['program','Programa']]){const wrap=el('label',label);const input=el(key==='role'?'select':'input');input.dataset.field=key;input.setAttribute('aria-label',label);if(key==='role'){for(const role of ['Conductor/a','Streamer','Panelista','Otro']){const option=el('option',role);input.append(option)}}else input.maxLength=key==='aliases'?1000:120;input.value=key==='aliases'?person.aliases.join(', '):person[key]||'';if(key==='name')input.required=true;wrap.append(input);row.append(wrap)}
 const remove=el('button','Quitar persona');remove.type='button';remove.onclick=()=>{row.remove();markDirty()};row.append(remove);$('people').append(row)}
function select(m){selected=m;$('editor').hidden=false;$('choose').hidden=true;$('edit-title').textContent='Editar '+m.name;for(const key of ['name','province','city','kind','publicationStatus','website','youtubeChannel','logo','logoTheme'])$('editor').elements.namedItem(key).value=m[key]||(key==='logoTheme'?'light':'');$('editor').elements.namedItem('topics').value=(m.topics||[]).join(', ');$('people').replaceChildren();(m.people||[]).forEach(personRow);markDirty(false);list();peopleOptions()}
async function load(){records=await api('/api/admin-media');$('workspace').hidden=false;$('login').hidden=true;$('logout').hidden=false;list();peopleOptions();await loadSubmissions()}
$('login-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('/api/admin-session',{method:'POST',body:JSON.stringify({password:$('password').value})});$('password').value='';await load();message('Sesión iniciada.')}catch(error){message(error.message)}finally{button.disabled=false}};
$('logout').onclick=async()=>{if(dirty&&!confirm('¿Cerrar sesión y descartar cambios sin guardar?'))return;try{await api('/api/admin-session',{method:'POST',body:JSON.stringify({action:'logout'})});markDirty(false);showLogin();message('Sesión cerrada.')}catch(error){message(error.message)}};
$('filter').oninput=list;$('editor').oninput=()=>markDirty();$('add-person').onclick=()=>{personRow();markDirty()};
$('reload').onclick=async()=>{if(dirty&&!confirm('¿Descartar cambios y recargar la lista?'))return;try{await load();selected=null;$('editor').hidden=true;$('choose').hidden=false;markDirty(false);message('Lista actualizada.')}catch(error){message(error.message)}};
$('editor').onsubmit=async e=>{e.preventDefault();if(!selected)return;const fields=Object.fromEntries(new FormData(e.target));fields.topics=fields.topics.split(',').map(x=>x.trim()).filter(Boolean);fields.people=[...$('people').children].map(row=>{const person={id:row.dataset.id};for(const input of row.querySelectorAll('[data-field]'))person[input.dataset.field]=input.dataset.field==='aliases'?input.value.split(',').map(x=>x.trim()).filter(Boolean):input.value.trim();return person});$('save').disabled=true;try{const result=await api('/api/admin-media',{method:'PATCH',body:JSON.stringify({id:selected.id,updatedAt:selected.updatedAt,media:fields})});Object.assign(selected,fields,{updatedAt:result.updatedAt});markDirty(false);list();peopleOptions();message('Cambios guardados. La guía los mostrará al recargar o en su próxima actualización.')}catch(error){message(error.message)}finally{$('save').disabled=false}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
api('/api/admin-session').then(async state=>{if(state.authenticated)await load();else{showLogin();if(!state.configured)message('Falta configurar ADMIN_PASSWORD y ADMIN_SESSION_SECRET en el servidor.')}}).catch(()=>message('No se pudo consultar el servidor.'));

function knownPeople(){const byId=new Map();for(const m of records)for(const person of m.people||[])if(!byId.has(person.id))byId.set(person.id,person);return [...byId.values()].sort((a,b)=>a.name.localeCompare(b.name,'es'))}
function peopleOptions(){const select=$('existing-person');select.replaceChildren(new Option('Elegí una persona…',''));for(const person of knownPeople())select.add(new Option(person.name,person.id))}
$('link-person').onclick=()=>{const person=knownPeople().find(p=>p.id===$('existing-person').value);if(!person)return;if([...$('people').children].some(row=>row.dataset.id===person.id)){message('Esa persona ya está vinculada.');return}personRow({...person,program:''});markDirty()};
async function loadSubmissions(){const rows=await api('/api/admin-submissions');$('pending-count').textContent='('+rows.length+')';$('submissions-list').replaceChildren();for(const row of rows){const card=el('article');card.className='submission';card.append(el('h3',row.name),el('p',row.city+' · '+row.province+' · '+row.kind));const link=el('a','Revisar sitio oficial ↗');link.href=row.website;link.target='_blank';link.rel='noopener noreferrer';card.append(link);
 for(const [action,label] of [['approve','Aceptar como borrador'],['reject','Rechazar']]){const b=el('button',label);b.type='button';b.onclick=async()=>{if(dirty){message('Guardá o descartá tu edición antes de revisar una propuesta.');return}if(!confirm(label+' de '+row.name+'?'))return;b.disabled=true;try{const result=await api('/api/admin-submissions',{method:'PATCH',body:JSON.stringify({id:row._id,action})});await load();if(result.mediaId)select(records.find(m=>m.id===result.mediaId));message(result.mediaId?'Borrador creado: verificá la ficha antes de publicarla.':'Propuesta rechazada.')}catch(error){message(error.message);b.disabled=false}};card.append(b)}$('submissions-list').append(card)}}
